import sys, json, re, hashlib, datetime

# THE ONE WRITER OF THE OBJECTS HIVE (GH #951). A thing a conversation keeps
# naming becomes a row: `thing_seen` (the curator's sidecar, carried by the
# assistants) counts sightings, a tool call of a model (`object_set`,
# `object_confirm`, forwarded by `./tools` on `edit`) changes a field. Nothing
# else writes `objects` or `keys`.
#
# APPEND-ONLY. A change is a NEW row `rev + 1` whose `supersedes` names the
# rev it replaces; no row is ever updated or deleted (the affinity gate's
# rule). The unique index (id, rev) is the compare-and-set: two writers that
# read the same head both insert `rev + 1`, one loses with `unique_violation`,
# reads the head again and decides again (at most RETRIES times).
#
# A ROW BELONGS TO THE ROUND IT WAS LEARNED IN. `audience_set` of a row is the
# canonical round of the turn that first saw it, and it is never widened. A
# later sighting counts for the row only when the row's round covers the
# sighting's round (`covers`: nobody of the new round is missing from the
# row's); otherwise the sighting starts a candidate row of its own -- two
# rounds never merge into one row (OR-BD-88: audience is the core risk).
#
# A sighting counts once per turn: the last MAX_TURNS turn ids are kept on the
# row, and a turn id already among them changes nothing (no new rev). A
# `candidate` becomes `active` at `promote_after` distinct turns, or at once
# when the owner confirms it (`./tools` decides who the owner is).
#
# After every write whose head is `active` -- and after a retirement of an
# active row -- `changed` hands the new row to `./push`, which announces the
# version to the graph space and asks memory for facts.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _int(key, default):
    v = P.get(key, default)
    try:
        return int(float(v))
    except Exception:
        return default


def _types(v):
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            v = [v]
    out = [str(x).strip() for x in (v if isinstance(v, list) else []) if str(x).strip()]
    return out or ["thing"]


TYPES = _types(P.get("types"))
PROMOTE_AFTER = max(1, _int("promote_after", 3))

ME = "gate"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
SLOTS = ("what", "where", "who", "when", "why", "how")
STATES = ("candidate", "active", "retired")
FIELDS = SLOTS + ("alias", "type", "state", "doc", "related")
ID_RE = re.compile(r"^ob-[0-9a-f]{12}$")
DOC_RE = re.compile(r"^fh-[0-9a-f]{12}(#\S{1,200})?$")
# A name is never an address (review O I-2): memory keys an alias and a fact
# subject in one normal form, so a name spelled like an object or file id could
# stand for another row's id, and that row's facts would answer this row's
# question in this row's round. Tested on the normal form, so case is no way in.
ADDR_NAME_RE = re.compile(r"^(ob|fh)-[0-9a-f]{12}")
# A person is named by a reference (`member:<id>`, an affinity ref), never by
# a name: a name in `who` would travel with every brief.
REF_RE = re.compile(r"^[a-z][a-z0-9_-]{0,31}:\S{1,120}$")
COLS = ["id", "rev", "type", "aliases", "state", "origin", "valid_since", "audience_set",
        "slots", "refs", "seen", "turns", "supersedes", "recorded_at"]
MAX_ITEMS = 8
NAME_MAX = 80
KIND_MAX = 32
NOTE_MAX = 200
MAX_TURNS = 16
MAX_ALIASES = 16
MAX_REFS = 32
MAX_IDS = 64
RETRIES = 3
NOT_FOUND = "no such object"


# ============================================================ PURE

def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def dumps(v):
    return json.dumps(v, sort_keys=True, ensure_ascii=False, separators=(",", ":"))


def loads(v, default):
    if isinstance(v, str):
        try:
            x = json.loads(v)
        except Exception:
            return default
        return x if isinstance(x, type(default)) else default
    return v if isinstance(v, type(default)) else default


# --8<-- round
# A round is `audience_set`: the JSON text of a list of strings. Canonical =
# sorted, without duplicates, without empty or non-string entries (GH #951,
# review of the memory seam: an empty name is nobody, and memory's
# `audience_now` must never carry a `""`); nothing left = "[]". Unparsable,
# empty text, not a list or absent = NO round; "[]" is a round (an empty one,
# roundless). `covers` is fail-closed: a row is visible to a question round
# exactly when nobody of the question is missing from the row's round ("*" in
# the row: everybody). A round is never widened.
def canon_round(v):
    if not isinstance(v, str) or not v.strip():
        return None
    try:
        xs = json.loads(v)
    except Exception:
        return None
    if not isinstance(xs, list):
        return None
    xs = [x for x in xs if isinstance(x, str) and x.strip()]
    return json.dumps(sorted(set(xs)), separators=(",", ":"))


def covers(row_aud, q):
    q = canon_round(q)
    r = canon_round(row_aud)
    if q is None or r is None:
        return False
    rs = json.loads(r)
    if "*" in rs:
        return True
    qs = json.loads(q)
    if not qs:
        # A roundless question sees only roundless rows: `set() <= rs` would
        # let it see every row of every round (#951, fail-closed).
        return not rs
    return set(qs) <= set(rs)
# --8<-- end round


# --8<-- norm-key
# The normal form of a name or alias: the memory hive store's `normalize`
# (crates/meclaw-cells/src/store/query/normalize.rs) in python, so that an
# object alias and a fact subject equate the same spellings (M.1). Lower case
# (`str.lower`, as rust `to_lowercase`), then the Latin-1 composition table of
# that file (a combining mark after its ASCII base letter becomes the
# precomposed letter), then trim + every run of whitespace -> one space. The
# whitespace set is rust's `char::is_whitespace` (Unicode White_Space), NOT
# python's `str.split()`, which also splits on U+001C..U+001F. No casefold.
# --8<-- normalize_text (copy of memory-hive writer, GH #948/#951)
# The memory hive's writer carries this function; this block is its copy
# word for word (gh951_one_spelling_one_key.rs), so that an alias and a
# fact subject meet under one key. Swap the whole block, never edit it here.
COMPOSE_ROWS = (
    ("\u0300", "aeiou", "\u00e0\u00e8\u00ec\u00f2\u00f9"),
    ("\u0301", "aeiouy", "\u00e1\u00e9\u00ed\u00f3\u00fa\u00fd"),
    ("\u0302", "aeiou", "\u00e2\u00ea\u00ee\u00f4\u00fb"),
    ("\u0303", "ano", "\u00e3\u00f1\u00f5"),
    ("\u0308", "aeiouy", "\u00e4\u00eb\u00ef\u00f6\u00fc\u00ff"),
    ("\u030a", "a", "\u00e5"),
    ("\u0327", "c", "\u00e7"),
)
COMPOSITIONS = {(base, mark): composed
                for mark, bases, composed_forms in COMPOSE_ROWS
                for base, composed in zip(bases, composed_forms)}
# Rust's `char::is_whitespace` (the Unicode White_Space property), spelled out:
# Python's `str.split()` also splits on U+001C..U+001F, which the store keeps.
WHITE_SPACE = frozenset("\t\n\x0b\x0c\r \x85\xa0\u1680\u2000\u2001\u2002\u2003"
                        "\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029"
                        "\u202f\u205f\u3000")


def normalize_text(value):
    """The normal form of one string -- the twin of `meclaw_norm` (0.2.0 P4).

    Same three effects in the same order as the store: case fold, Latin-1
    composition (NFD -> NFC), whitespace collapse over the store's own
    whitespace. An unrecognised mark leaves the two spellings DIFFERENT, which
    is the same conservatism the Rust side ships.
    """
    out = []
    for ch in str(value or "").lower():
        composed = COMPOSITIONS.get((out[-1], ch)) if out else None
        if composed is None:
            out.append(ch)
        else:
            out[-1] = composed
    words, word = [], []
    for ch in out:
        if ch in WHITE_SPACE:
            if word:
                words.append("".join(word))
                word = []
        else:
            word.append(ch)
    if word:
        words.append("".join(word))
    return " ".join(words)
# --8<-- end normalize_text


def norm_key(s):
    return normalize_text(s)
# --8<-- end norm-key


def new_id(key, round_):
    """`ob-` + the first 12 hex digits of sha256(key + newline + round): the
    same name learned in two rounds is two objects."""
    return "ob-" + hashlib.sha256((key + "\n" + round_).encode("utf-8")).hexdigest()[:12]


def v12(oid, rev):
    return hashlib.sha256(("%s:%d" % (oid, int(rev))).encode("utf-8")).hexdigest()[:12]


def empty_slots():
    return {"what": "", "where": "", "who": [], "when": "", "why": "", "how": ""}


def clean_items(raw):
    """The valid items of one `thing_seen`, one per normal form, in order: a
    name of 1..80 characters is kept, a name in the form of an address is
    dropped, a too long kind or note is dropped (the item stays), at most
    MAX_ITEMS."""
    out, seen = [], set()
    for it in raw if isinstance(raw, list) else []:
        if len(out) >= MAX_ITEMS:
            break
        if not isinstance(it, dict):
            continue
        name = it.get("name")
        if not isinstance(name, str):
            continue
        name = " ".join(name.split())
        if not name or len(name) > NAME_MAX:
            continue
        key = norm_key(name)
        if not key or key in seen or ADDR_NAME_RE.match(key):
            continue
        seen.add(key)
        kind = it.get("kind")
        kind = kind.strip() if isinstance(kind, str) and len(kind) <= KIND_MAX else ""
        note = it.get("note")
        note = " ".join(note.split()) if isinstance(note, str) and len(note) <= NOTE_MAX else ""
        out.append({"key": key, "name": name, "kind": kind, "note": note})
    return out


def pick(cands):
    """The row a sighting counts for among the covering rows: not retired
    first, then the oldest (`valid_since`), then the id."""
    if not cands:
        return None
    return sorted(cands, key=lambda r: (r.get("state") == "retired",
                                        str(r.get("valid_since") or ""),
                                        str(r.get("id") or "")))[0]


def next_row(head, stamp):
    """A copy of `head` as the next rev (supersedes the head)."""
    row = {c: head.get(c) for c in COLS}
    row["rev"] = int(head.get("rev") or 0) + 1
    row["supersedes"] = int(head.get("rev") or 0)
    row["recorded_at"] = stamp
    return row


def decide_seen(items, keymap, heads, round_, turn, stamp, types=None, promote=None):
    """The writes of one `thing_seen`, pure: [(row, prev_state, item_keys)].
    `keymap` {key: [ids]}, `heads` {id: head row}. A sighting whose turn the
    row already holds writes nothing."""
    types = types or TYPES
    promote = promote or PROMOTE_AFTER
    by_id, order = {}, []
    fresh = []
    for it in items:
        cands = [heads[i] for i in keymap.get(it["key"], []) if i in heads
                 and covers(heads[i].get("audience_set"), round_)]
        hit = pick(cands)
        if hit is None:
            fresh.append(it)
            continue
        oid = hit["id"]
        if oid not in by_id:
            by_id[oid] = (hit, [])
            order.append(oid)
        by_id[oid][1].append(it["key"])
    out = []
    for oid in order:
        head, keys = by_id[oid]
        turns = loads(head.get("turns"), [])
        if turn in turns:
            continue
        row = next_row(head, stamp)
        row["turns"] = dumps((turns + [turn])[-MAX_TURNS:])
        row["seen"] = int(head.get("seen") or 0) + 1
        if head.get("state") == "candidate" and row["seen"] >= promote:
            row["state"] = "active"
        out.append((row, str(head.get("state") or ""), keys))
    for it in fresh:
        slots = empty_slots()
        if it["note"]:
            slots["what"] = it["note"]
        row = {"id": new_id(it["key"], round_), "rev": 1,
               "type": it["kind"] if it["kind"] in types else types[0],
               "aliases": dumps([it["name"]]),
               "state": "active" if promote <= 1 else "candidate",
               "origin": "thing_seen", "valid_since": stamp, "audience_set": round_,
               "slots": dumps(slots), "refs": dumps({"doc": [], "related": []}),
               "seen": 1, "turns": dumps([turn]), "supersedes": 0, "recorded_at": stamp}
        out.append((row, "", [it["key"]]))
    return out


def apply_edit(head, op, field, value, stamp, types=None):
    """(new row | None, error code | ''): one tool change on `head`. None
    without an error = nothing to change (no new rev)."""
    types = types or TYPES
    value = value if isinstance(value, str) else ""
    row = next_row(head, stamp)
    if op == "confirm":
        if head.get("state") == "active":
            return None, ""
        row["state"] = "active"
        return row, ""
    if op != "set" or field not in FIELDS:
        return None, "bad_request"
    slots = empty_slots()
    slots.update(loads(head.get("slots"), {}))
    refs = {"doc": [], "related": []}
    refs.update(loads(head.get("refs"), {}))
    aliases = loads(head.get("aliases"), [])
    v = value.strip()
    if field == "who":
        who = [x for x in slots.get("who") or [] if isinstance(x, str)]
        if not v:
            who = []
        elif not REF_RE.match(v):
            return None, "bad_request"
        elif v not in who:
            if len(who) >= MAX_REFS:
                return None, "too_many"
            who = who + [v]
        slots["who"] = who
    elif field in SLOTS:
        slots[field] = " ".join(value.split())
    elif field == "alias":
        name = " ".join(value.split())
        key = norm_key(name)
        if not key or len(name) > NAME_MAX or ADDR_NAME_RE.match(key):
            return None, "bad_request"
        if any(norm_key(a) == key for a in aliases):
            return None, ""
        if len(aliases) >= MAX_ALIASES:
            return None, "too_many"
        aliases = aliases + [name]
    elif field == "type":
        if v not in types:
            return None, "bad_type"
        row["type"] = v
    elif field == "state":
        if v not in STATES:
            return None, "bad_request"
        row["state"] = v
    elif field in ("doc", "related"):
        cur = [x for x in refs.get(field) or [] if isinstance(x, str)]
        ok = DOC_RE.match(v) if field == "doc" else (ID_RE.match(v) and v != head.get("id"))
        if not v:
            cur = []
        elif not ok:
            return None, "bad_request"
        elif v not in cur:
            if len(cur) >= MAX_REFS:
                return None, "too_many"
            cur = cur + [v]
        refs[field] = cur
    row["slots"] = dumps(slots)
    row["refs"] = dumps(refs)
    row["aliases"] = dumps(aliases)
    same = all(row.get(c) == head.get(c) for c in ("type", "state")) and \
        loads(head.get("slots"), {}) == slots and loads(head.get("refs"), {}) == refs and \
        loads(head.get("aliases"), []) == aliases
    return (None, "") if same else (row, "")


def announces(row, prev_state):
    """Whether a written row is news for `./push`: an active head, or an
    active row retired."""
    st = row.get("state")
    return st == "active" or (st == "retired" and prev_state == "active")


# ============================================================ PLUMBING

def emit(msgs):
    for m in msgs:
        if isinstance(m, dict) and "messages" not in m:
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs, ensure_ascii=False))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("objects/gate: %s\n" % reason)
    emit([])


def store(ops, phase, carry):
    return {"header": {"route": "gate_store", "phase": phase, "reply_cell": ME,
                       "cur_call": json.dumps(carry, sort_keys=True, ensure_ascii=False)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(a, ensure_ascii=False)} for cid, a in ops]}


def head_op(oid):
    return {"operation": "select", "table": "objects", "columns": COLS,
            "where": {"id": oid}, "order_by": [{"col": "rev", "dir": "desc"}], "limit": 1}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": "", "rows": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": "", "rows": 0})
                leg["error_code"] = str(r.get("error_code") or "")
                leg["rows"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["rows"] = int(hop.get("rows_affected") or 0)
    return out


def rows_of(leg):
    p = (leg or {}).get("payload")
    return [r for r in p if isinstance(r, dict)] if isinstance(p, list) else []


def changed(row, prev_state):
    return {"header": {"route": "changed"}, "row": row, "prev_state": prev_state}


def answer(c, fields=None, code="", message=""):
    h = {"route": "answer", "op": str(c.get("op") or ""), "op_id": str(c.get("op_id") or ""),
         "caller": str(c.get("caller") or "tools")}
    if code:
        body = {"ok": False, "op": h["op"], "error": {"code": code, "message": message}}
    else:
        body = {"ok": True, "op": h["op"]}
        body.update(fields or {})
    body["header"] = h
    return body


def done(c, row):
    return answer(c, {"id": row["id"], "state": row["state"],
                      "version": v12(row["id"], row["rev"])})


def seen_keys(c):
    keys = [it["key"] for it in c["items"]]
    return store([("k", {"operation": "select", "table": "keys", "columns": ["key", "id"],
                         "where": {"key": {"in": keys}}, "limit": 400})], "seen-keys", c)


def seen_write(c, keymap, heads, stamp):
    writes = decide_seen(c["items"], keymap, heads, c["round"], c["turn"], stamp)
    if not writes:
        emit([])
    ops, plan = [], []
    for i, (row, prev, keys) in enumerate(writes):
        ops.append(("w%d" % i, {"operation": "insert", "table": "objects", "row": row}))
        if row["rev"] == 1:
            ops.append(("k%d" % i, {"operation": "insert", "table": "keys",
                                    "row": {"key": keys[0], "id": row["id"], "at": stamp}}))
        plan.append({"leg": "w%d" % i, "row": row, "prev_state": prev, "keys": keys})
    c = dict(c, plan=plan)
    emit([store(ops, "seen-write", c)])


def edit_write(c, head, stamp):
    row, err = apply_edit(head, c.get("op"), c.get("slot"), c.get("value"), stamp)
    if err:
        emit([answer(c, code=err, message="the change is refused: %s" % err)])
    if row is None:
        emit([done(c, head)])
    ops = [("w", {"operation": "insert", "table": "objects", "row": row})]
    if c.get("slot") == "alias":
        ops.append(("k", {"operation": "insert", "table": "keys",
                          "row": {"key": norm_key(c.get("value")), "id": row["id"], "at": stamp}}))
    emit([store(ops, "edit-write", dict(c, row=row, prev_state=head.get("state")))])


# ============================================================ LANES

lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")

if lane == "thing_seen":
    round_ = canon_round(ctx.get("audience_set"))
    if round_ is None:
        park("thing_seen without a round (context.audience_set) -- dropped, nothing written")
    turn = str(d.get("turn_id") or d.get("episode_turn_id") or "").strip()
    if not turn:
        park("thing_seen without a turn_id -- dropped, nothing written")
    items = clean_items(d.get("items"))
    if not items:
        park("thing_seen without a valid item -- dropped")
    emit([seen_keys({"do": "seen", "round": round_, "turn": turn[:200], "items": items,
                     "try": 0})])

if lane == "edit":
    c = {"do": "edit", "op": str(d.get("op") or hop.get("op") or ""),
         "id": str(d.get("id") or ""), "slot": str(d.get("slot") or ""),
         "value": d.get("value") if isinstance(d.get("value"), str) else "",
         "round": canon_round(d.get("round")), "op_id": str(hop.get("op_id") or ""),
         "caller": str(hop.get("caller") or "tools"), "try": 0}
    if c["round"] is None:
        emit([answer(c, code="missing_audience", message="the call carries no round")])
    if not ID_RE.match(c["id"]):
        emit([answer(c, code="not_found", message=NOT_FOUND)])
    emit([store([("h", head_op(c["id"]))], "edit-head", c)])

if lane:
    park("unknown lane %r -- dropped" % lane)
if not hop.get("operation"):
    park("a message with neither a lane nor a store answer -- dropped")

c = loads(ctx.get("cur_call"), {})
lg = legs(d)

if phase == "seen-keys":
    keymap = {}
    for r in rows_of(lg.get("k")):
        ids_of = keymap.setdefault(str(r.get("key") or ""), [])
        if str(r.get("id") or "") not in ids_of:
            ids_of.append(str(r.get("id") or ""))
    ids = sorted({i for v in keymap.values() for i in v if ID_RE.match(i)})[:MAX_IDS]
    c = dict(c, keymap=keymap)
    if not ids:
        seen_write(c, keymap, {}, now())
    emit([store([("h%d" % n, head_op(i)) for n, i in enumerate(ids)], "seen-heads", c)])

if phase == "seen-heads":
    heads = {}
    for cid, leg in lg.items():
        for r in rows_of(leg):
            heads[str(r.get("id"))] = r
    seen_write(c, c.get("keymap") or {}, heads, now())

if phase == "seen-write":
    out, lost = [], []
    for w in c.get("plan") or []:
        leg = lg.get(w["leg"]) or {}
        code = leg.get("error_code") or ""
        if not code:
            if announces(w["row"], w["prev_state"]):
                out.append(changed(w["row"], w["prev_state"]))
        elif code == "unique_violation":
            lost.extend(w["keys"])
        else:
            sys.stderr.write("objects/gate: the store refused %s (%s)\n" % (w["row"]["id"], code))
    if lost:
        if int(c.get("try") or 0) + 1 >= RETRIES:
            sys.stderr.write("objects/gate: lost the write of %s %d times -- dropped\n"
                             % (", ".join(lost), RETRIES))
        else:
            items = [it for it in c["items"] if it["key"] in lost]
            out.append(seen_keys({"do": "seen", "round": c["round"], "turn": c["turn"],
                                  "items": items, "try": int(c.get("try") or 0) + 1}))
    emit(out)

if phase == "edit-head":
    head = (rows_of(lg.get("h")) or [None])[0]
    if head is None or not covers(head.get("audience_set"), c.get("round")):
        # The same answer for a row that does not exist and a row this round
        # may not see: no hint of existence (O.5).
        emit([answer(c, code="not_found", message=NOT_FOUND)])
    edit_write(c, head, now())

if phase == "edit-write":
    leg = lg.get("w") or {}
    code = leg.get("error_code") or ""
    if not code:
        row = c["row"]
        out = [done(c, row)]
        if announces(row, c.get("prev_state")):
            out.append(changed(row, c.get("prev_state")))
        emit(out)
    if code == "unique_violation" and int(c.get("try") or 0) + 1 < RETRIES:
        c = {k: v for k, v in c.items() if k not in ("row", "prev_state")}
        c["try"] = int(c.get("try") or 0) + 1
        emit([store([("h", head_op(c["id"]))], "edit-head", c)])
    emit([answer(c, code="busy" if code == "unique_violation" else "store_error",
                 message="the change was not written (%s)" % code)])

park("unknown phase %r -- dropped" % phase)
